@[simp]
theorem symm_comp {f₁ : a ⟶ b} {g₁ : b ⟶ a} {f₂ : b ⟶ c} {g₂ : c ⟶ b}
    (P : f₁ ⊣⊢ g₁) (Q : f₂ ⊣⊢ g₂) : (P.comp Q).symm = Q.symm.comp P.symm

theorem IsCyclic.comp {P : f ⊣⊢ g} {P' : f' ⊣⊢ g'} {P'' : f'' ⊣⊢ g''} {α : f ⟶ f'}
    {β : f' ⟶ f''} (hα : IsCyclic P P' α) (hβ : IsCyclic P' P'' β) :
    IsCyclic P P'' (α ≫ β)

theorem IsCyclic.whiskerLeft {P : f ⊣⊢ g} {P' : f' ⊣⊢ g'} {α : f ⟶ f'}
    (hα : IsCyclic P P' α) {h : c ⟶ a} {k : a ⟶ c} (R : h ⊣⊢ k) :
    IsCyclic (R.comp P) (R.comp P') (h ◁ α)

theorem IsCyclic.whiskerRight {P : f ⊣⊢ g} {P' : f' ⊣⊢ g'} {α : f ⟶ f'}
    (hα : IsCyclic P P' α) {h : b ⟶ c} {k : c ⟶ b} (R : h ⊣⊢ k) :
    IsCyclic (P.comp R) (P'.comp R) (α ▷ h)

theorem leftMate_whiskerLeft (P : f ⊣⊢ g) (P' : f' ⊣⊢ g') {h : c ⟶ a} {k : a ⟶ c}
    (R : h ⊣⊢ k) (α : f ⟶ f') :
    leftMate (R.comp P) (R.comp P') (h ◁ α) = leftMate P P' α ▷ k

theorem leftMate_whiskerRight (P : f ⊣⊢ g) (P' : f' ⊣⊢ g') {h : b ⟶ c} {k : c ⟶ b}
    (R : h ⊣⊢ k) (α : f ⟶ f') :
    leftMate (P.comp R) (P'.comp R) (α ▷ h) = k ◁ leftMate P P' α

theorem rightMate_whiskerLeft (P : f ⊣⊢ g) (P' : f' ⊣⊢ g') {h : c ⟶ a} {k : a ⟶ c}
    (R : h ⊣⊢ k) (α : f ⟶ f') :
    rightMate (R.comp P) (R.comp P') (h ◁ α) = rightMate P P' α ▷ k

theorem rightMate_whiskerRight (P : f ⊣⊢ g) (P' : f' ⊣⊢ g') {h : b ⟶ c} {k : c ⟶ b}
    (R : h ⊣⊢ k) (α : f ⟶ f') :
    rightMate (P.comp R) (P'.comp R) (α ▷ h) = k ◁ rightMate P P' α

theorem leftTrace_comp_comm_of_isCyclic_left {P : f ⊣⊢ g} {P' : f' ⊣⊢ g'} {α : f ⟶ f'}
    (hα : IsCyclic P P' α) (β : f' ⟶ f) :
    leftTrace P (α ≫ β) = leftTrace P' (β ≫ α)

theorem rightTrace_comp_comm_of_isCyclic_left {P : f ⊣⊢ g} {P' : f' ⊣⊢ g'} {α : f ⟶ f'}
    (hα : IsCyclic P P' α) (β : f' ⟶ f) :
    rightTrace P (α ≫ β) = rightTrace P' (β ≫ α)

theorem leftZigzag_eq {B : Type*} [Bicategory B] {a b : B} {f : a ⟶ b} {g : b ⟶ a}
    (η : 𝟙 a ⟶ f ≫ g) (ε : g ≫ f ⟶ 𝟙 b) :
    leftZigzag η ε = η ▷ f ≫ (α_ f g f).hom ≫ f ◁ ε

theorem rightZigzag_eq {B : Type*} [Bicategory B] {a b : B} {f : a ⟶ b} {g : b ⟶ a}
    (η : 𝟙 a ⟶ f ≫ g) (ε : g ≫ f ⟶ 𝟙 b) :
    rightZigzag η ε = g ◁ η ≫ (α_ g f g).inv ≫ ε ▷ g

theorem hom_induction {a b : Obj S} {p : (P.obj a ⟶ P.obj b) → Prop}
    (diag : ∀ d : a ⟶ b, p (P.diag d)) (zero : p 0) (add : ∀ f g, p f → p g → p (f + g))
    (smul : ∀ (r : R) f, p f → p (r • f)) (f : P.obj a ⟶ P.obj b) : p f

theorem rel_mem_homDeg (deg : S.Gen → A) (R : Type w) [CommRing R] {x : InterchangeData S}
    (hx : x.Valid) :
    rel R hx ∈ LinDiagram.homDeg R deg x.dom x.cod (deg x.g + deg x.h)

theorem cast_mem_homDeg {a' b' : Obj S} {f : LinDiagram R a b} {d : A}
    (hf : f ∈ homDeg R deg a b d) (ha : a = a') (hb : b = b') :
    cast f ha hb ∈ homDeg R deg a' b' d

theorem comp_mem_homDeg {f : LinDiagram R a b} {g : LinDiagram R b c} {d e : A}
    (hf : f ∈ homDeg R deg a b d) (hg : g ∈ homDeg R deg b c e) :
    f ≫ g ∈ homDeg R deg a c (d + e)

theorem comp_mem_homDeg {f : P.obj a ⟶ P.obj b} {g : P.obj b ⟶ P.obj c} {d e : A}
    (hf : f ∈ P.homDeg deg a b d) (hg : g ∈ P.homDeg deg b c e) :
    f ≫ g ∈ P.homDeg deg a c (d + e)

theorem homogeneousComponent_of_mem (hP : P.IsHomogeneous deg) {d : A}
    {x : P.obj a ⟶ P.obj b} (hx : x ∈ P.homDeg deg a b d) :
    homogeneousComponent hP d x = x

theorem homogeneousComponent_of_mem_of_ne (hP : P.IsHomogeneous deg) {d e : A}
    {x : P.obj a ⟶ P.obj b} (hx : x ∈ P.homDeg deg a b e) (h : e ≠ d) :
    homogeneousComponent hP d x = 0

theorem parity_comp {X Y Z : C} {p q : ZMod 2} {f : X ⟶ Y} {g : Y ⟶ Z}
    (hf : IsHomogeneous (R := R) f p) (hg : IsHomogeneous (R := R) g q) :
    IsHomogeneous (R := R) (f ≫ g) (p + q)

theorem IsSuperfunctor.map_isHomogeneous (F : C ⥤ D) [F.Additive] [F.Linear R]
    [IsSuperfunctor R F] {X Y : C} {p : ZMod 2} {f : X ⟶ Y}
    (hf : IsHomogeneous (R := R) f p) : IsHomogeneous (R := R) (F.map f) p

theorem interchange_of_even_left {X X' Y Y' : C} {q : ZMod 2} {f : X ⟶ X'} {g : Y ⟶ Y'}
    (hf : f ∈ parity (R := R) X X' 0) (hg : g ∈ parity (R := R) Y Y' q) :
    f ▷ Y ≫ X' ◁ g = X ◁ g ≫ f ▷ Y'

theorem interchange_of_even_right {X X' Y Y' : C} {p : ZMod 2} {f : X ⟶ X'} {g : Y ⟶ Y'}
    (hf : f ∈ parity (R := R) X X' p) (hg : g ∈ parity (R := R) Y Y' 0) :
    f ▷ Y ≫ X' ◁ g = X ◁ g ≫ f ▷ Y'

theorem interchange_of_odd {X X' Y Y' : C} {f : X ⟶ X'} {g : Y ⟶ Y'}
    (hf : f ∈ parity (R := R) X X' 1) (hg : g ∈ parity (R := R) Y Y' 1) :
    f ▷ Y ≫ X' ◁ g = -(X ◁ g ≫ f ▷ Y')

theorem superTensorHom_mem {X₁ Y₁ X₂ Y₂ : C} {p q : ZMod 2} {f : X₁ ⟶ Y₁} {g : X₂ ⟶ Y₂}
    (hf : f ∈ parity (R := R) X₁ Y₁ p) (hg : g ∈ parity (R := R) X₂ Y₂ q) :
    superTensorHom f g ∈ parity (R := R) (X₁ ⊗ X₂) (Y₁ ⊗ Y₂) (p + q)

theorem tensorHom_eq_superTensorHom {X₁ Y₁ X₂ Y₂ : C} {p q : ZMod 2} {f : X₁ ⟶ Y₁}
    {g : X₂ ⟶ Y₂} (hf : f ∈ parity (R := R) X₁ Y₁ p) (hg : g ∈ parity (R := R) X₂ Y₂ q) :
    f ⊗ₘ g = koszulSign p q • superTensorHom f g

theorem tensorHom_mem {X₁ Y₁ X₂ Y₂ : C} {p q : ZMod 2} {f : X₁ ⟶ Y₁} {g : X₂ ⟶ Y₂}
    (hf : f ∈ parity (R := R) X₁ Y₁ p) (hg : g ∈ parity (R := R) X₂ Y₂ q) :
    f ⊗ₘ g ∈ parity (R := R) (X₁ ⊗ X₂) (Y₁ ⊗ Y₂) (p + q)

theorem hcomp_eq {a b c : B} {f g : a ⟶ b} {h i : b ⟶ c} {p q : ZMod 2} {x : f ⟶ g}
    {y : h ⟶ i} (hx : x ∈ parity (R := R) f g p) (hy : y ∈ parity (R := R) h i q) :
    hcomp x y = koszulSign p q • (f ◁ y ≫ x ▷ i)

theorem hcomp_mem {a b c : B} {f g : a ⟶ b} {h i : b ⟶ c} {p q : ZMod 2} {x : f ⟶ g}
    {y : h ⟶ i} (hx : x ∈ parity (R := R) f g p) (hy : y ∈ parity (R := R) h i q) :
    hcomp x y ∈ parity (R := R) (f ≫ h) (g ≫ i) (p + q)

theorem homDeg_induction {A : Type*} [AddCommMonoid A] {deg : S.Gen → A} {a b : Obj S} {d : A}
    {motive : (P.obj a ⟶ P.obj b) → Prop}
    (diag : ∀ f : a ⟶ b, Diagram.degree deg f = d → motive (P.diag f)) (zero : motive 0)
    (add : ∀ x y, motive x → motive y → motive (x + y))
    (smul : ∀ (r : R) x, motive x → motive (r • x)) {x : P.obj a ⟶ P.obj b}
    (hx : x ∈ P.homDeg deg a b d) : motive x

theorem wL_mem {A : Type*} [AddCommMonoid A] (deg : S.Gen → A) (a : Obj S) {b b' : Obj S}
    {d : A} {g : P.obj b ⟶ P.obj b'} (hg : g ∈ P.homDeg deg b b' d) :
    P.wL a g ∈ P.homDeg deg (a.tensor b) (a.tensor b') d

theorem wR_mem {A : Type*} [AddCommMonoid A] (deg : S.Gen → A) {a a' : Obj S} {d : A}
    {f : P.obj a ⟶ P.obj a'} (hf : f ∈ P.homDeg deg a a' d) (b : Obj S) :
    P.wR f b ∈ P.homDeg deg (a.tensor b) (a'.tensor b) d

theorem idAt_insAt {g : ℕ} (hg : g ≤ s.length) (k : ℕ) (a b : α) (i : ℕ) :
    idAt (insAt s g (k, a) (k, b)) i = if i < g then idAt s i else if i = g then some k
      else if i = g + 1 then some k else idAt s (i - 2)

theorem ExHyp.apply {n : ℕ} (ih : ExHyp (α := α) n) {t : List (ℕ × α)} (hv : Valid t) {q : ℕ}
    (h : Ilv t q) (hn : t.length + cr t < n) :
    Equiv (canon t) (canon (swapAt t q) ++ [.cross q])

theorem Iso.insAt {u t : List (ℕ × α)} (h : Iso u t) {g : ℕ} (hg : g ≤ u.length) {k k' : ℕ}
    (hk : ∀ x ∈ u, x.1 ≠ k) (hk' : ∀ x ∈ t, x.1 ≠ k') (a b : α) :
    Iso (Chord.insAt u g (k, a) (k, b)) (Chord.insAt t g (k', a) (k', b))

theorem Near.cons {n : ℕ} {l : List α} {X Y : List (Move α)} {m : Move α}
    (h : Φ.Near n (lstep d l m) X Y) (hm : m.Ok l.length) :
    Φ.Near (m.ncross + n) l (m :: X) (m :: Y)

theorem mem_eval_comp {n : ℕ} {l l' : List α} {D : List (Move α)}
    {x : F.obj (D.foldl (lstep d) l) ⟶ F.obj l'} (hx : x ∈ Φ.sub n _ l') (hf : Fits l.length D) :
    F.eval l D ≫ x ∈ Φ.sub (ncross D + n) l l'

theorem near_of_diag_eq (Φ : (G.interp r₀ P).Filtration) {n : ℕ} {l : List S.Colour}
    {X Y : List (Move S.Colour)}
    (h : ∀ f₁ f₂ : (⟨r₀, l⟩ : Obj S) ⟶ ⟨r₀, Y.foldl (lstep d) l⟩,
      Diagram.layers f₁ = G.layersOf r₀ l X → Diagram.layers f₂ = G.layersOf r₀ l Y →
        P.diag f₁ = P.diag f₂) :
    Φ.Near n l X Y

theorem diag_sep (ρ : S.Region) (u w₁ mid w₂ t : List α) {m₁ m₂ : Move α}
    (h₁ : m₁.Ok w₁.length) (h₂ : m₂.Ok w₂.length) {l : List α}
    (hl : l = u ++ w₁ ++ mid ++ w₂ ++ t) {X Y : List (Move α)}
    (hX : X = [m₁.shift u.length, m₂.shift (u ++ lstep d w₁ m₁ ++ mid).length])
    (hY : Y = [m₂.shift (u ++ w₁ ++ mid).length, m₁.shift u.length]) {B : Obj S}
    (f₁ f₂ : Λ.obj ρ l ⟶ B) (hf₁ : Diagram.layers f₁ = G.layersOf ρ l X)
    (hf₂ : Diagram.layers f₂ = G.layersOf ρ l Y) :
    P.diag f₁ = P.diag f₂

theorem layerWeight_moveLayers (hcup : ∀ ρ a, layerWeight wt (G.cup ρ a) = 0)
    (hcross : ∀ ρ a b, layerWeight wt (G.cross ρ a b) = 1) (ρ : S.Region) {l : List α}
    {m : Move α} (hm : m.Ok l.length) : layerWeight wt (G.moveLayers ρ l m) = m.ncross

theorem near_of_diag_eq (ρ : S.Region) (Φ : (G.interp P ρ).Filtration) {n : ℕ} {l : List α}
    {X Y : List (Move α)}
    (h : ∀ f₁ f₂ : Λ.obj ρ l ⟶ Λ.obj ρ (Y.foldl (lstep d) l),
      Diagram.layers f₁ = G.layersOf ρ l X → Diagram.layers f₂ = G.layersOf ρ l Y →
        P.diag f₁ = P.diag f₂) :
    Φ.Near n l X Y

theorem near_uu {n g g' : ℕ} (a b : α) (hg : g' ≤ g) {l : List α}
    (hf : Fits l.length [(.cup g a : Move α), .cup g' b]) :
    Φ.Near n l [.cup g a, .cup g' b] [.cup g' b, .cup (g + 2) a]

theorem near_xuL {n p g : ℕ} (a : α) (hp : p + 2 ≤ g) {l : List α}
    (hf : Fits l.length [.cross p, (.cup g a : Move α)]) :
    Φ.Near n l [.cross p, .cup g a] [.cup g a, .cross p]

theorem near_xuR {n p g : ℕ} (a : α) (hg : g ≤ p) {l : List α}
    (hf : Fits l.length [.cross p, (.cup g a : Move α)]) :
    Φ.Near n l [.cross p, .cup g a] [.cup g a, .cross (p + 2)]

theorem near_xx {n p p' : ℕ} (hp : p + 2 ≤ p') {l : List α}
    (hf : Fits l.length ([.cross p, .cross p'] : List (Move α))) :
    Φ.Near n l [.cross p, .cross p'] [.cross p', .cross p]

theorem deriv_deriv_eq_zero
    (h : ∀ g : S.Gen, P.deriv hP (P.deriv hP (P.diag (ofGen g))) = 0) {a b : Obj S}
    (f : P.obj a ⟶ P.obj b) : P.deriv hP (P.deriv hP f) = 0

theorem nil_comp_comm_super (r : S.Region) {p q : ZMod 2}
    {f g : P.obj (Obj.nil r) ⟶ P.obj (Obj.nil r)}
    (hf : f ∈ P.homDeg (parityDeg S) (Obj.nil r) (Obj.nil r) p)
    (hg : g ∈ P.homDeg (parityDeg S) (Obj.nil r) (Obj.nil r) q) :
    f ≫ g = koszulSign p q • (g ≫ f)

theorem hom_induction_int (P : Presentation S ℤ) {p : (P.obj a ⟶ P.obj b) → Prop}
    (diag : ∀ d : a ⟶ b, p (P.diag d)) (zero : p 0) (add : ∀ f g, p f → p g → p (f + g))
    (neg : ∀ f, p f → p (-f)) (f : P.obj a ⟶ P.obj b) : p f

theorem PmEq.evW_cons_cap {a i : ℕ} {v v' : List Step} {c : ℕ}
    (h : PmEq (evW R δ a v c) (evW R δ a v' c)) :
    PmEq (evW R δ (a + 2) (.cap i :: v) c) (evW R δ (a + 2) (.cap i :: v') c)

theorem PmEq.evW_cons_cup {a i : ℕ} {v v' : List Step} {c : ℕ}
    (h : PmEq (evW R δ (a + 2) v c) (evW R δ (a + 2) v' c)) :
    PmEq (evW R δ a (.cup i :: v) c) (evW R δ a (.cup i :: v') c)

theorem PmEq.evW_prefix {a : ℕ} (w : List Step) {b : ℕ} (hb : ht a w = b) {v v' : List Step}
    {c : ℕ} (h : PmEq (evW R δ b v c) (evW R δ b v' c)) :
    PmEq (evW R δ a (w ++ v) c) (evW R δ a (w ++ v') c)

theorem proj_comp_of_mem_left {p : ZMod 2} (q : ZMod 2) {X Y Z : C} {f : X ⟶ Y}
    (hf : f ∈ parity (R := R) X Y p) (g : Y ⟶ Z) :
    proj R (p + q) (f ≫ g) = f ≫ proj R q g

theorem proj_comp_of_mem_right (p : ZMod 2) {q : ZMod 2} {X Y Z : C} (f : X ⟶ Y) {g : Y ⟶ Z}
    (hg : g ∈ parity (R := R) Y Z q) :
    proj R (p + q) (f ≫ g) = proj R p f ≫ g

theorem map_mem (F : C ⥤ D) [F.Additive] [F.Linear R] [IsSuperfunctor R F] {X Y : C}
    {p : ZMod 2} {f : X ⟶ Y} (hf : f ∈ parity (R := R) X Y p) :
    F.map f ∈ parity (R := R) (F.obj X) (F.obj Y) p

theorem map_proj (F : C ⥤ D) [F.Additive] [F.Linear R] [IsSuperfunctor R F] (p : ZMod 2) {X Y : C}
    (f : X ⟶ Y) :
    F.map (proj R p f) = proj R p (F.map f)

theorem ζ_naturality_of_mem {X Y : C} {q : ZMod 2} {f : X ⟶ Y}
    (hf : f ∈ parity (R := R) X Y q) :
    (pi (R := R)).map f ≫ (ζ (R := R) Y).hom = sign R q • ((ζ (R := R) X).hom ≫ f)

theorem ofHom_mem {X Y : Envelope R C} {f : X.obj ⟶ Y.obj} {q : ZMod 2}
    (hf : f ∈ parity (R := R) X.obj Y.obj q) :
    ofHom f ∈ parity (R := R) X Y (q + (X.par + Y.par))

@[simp] theorem layers_dlay (i : ℕ) (g : S.Gen) (j : ℕ) {n m : ℕ}
    (hn : i + (S.dom g).length + j = n) (hm : i + (S.cod g).length + j = m) :
    Diagram.layers (dlay i g j hn hm) = [lay i g j]

theorem hcomp₂_hcomp₂_associator {a b c d : B} {f f' : a ⟶ b} {g g' : b ⟶ c} {h h' : c ⟶ d}
    (η : f ⟶ f') (θ : g ⟶ g') (ι : h ⟶ h') :
    hcomp₂ (hcomp₂ η θ) ι ≫ (α_ f' g' h').hom = (α_ f g h).hom ≫ hcomp₂ η (hcomp₂ θ ι)

theorem hcomp₂_hcomp₂_associator_inv {a b c d : B} {f f' : a ⟶ b} {g g' : b ⟶ c} {h h' : c ⟶ d}
    (η : f ⟶ f') (θ : g ⟶ g') (ι : h ⟶ h') :
    hcomp₂ η (hcomp₂ θ ι) ≫ (α_ f' g' h').inv = (α_ f g h).inv ≫ hcomp₂ (hcomp₂ η θ) ι

theorem hcomp_eq {p q : ZMod 2} {x : F ⟶ H} {y : G' ⟶ K'}
    (hx : x ∈ parity (R := R) F H p) (hy : y ∈ parity (R := R) G' K' q) :
    hcomp x y = koszulSign p q • (whiskerLeft F y ≫ whiskerRight x K')

theorem whiskerLeft_mem (F : Superfunctor R C D) {p : ZMod 2} {y : G' ⟶ K'}
    (hy : y ∈ parity (R := R) G' K' p) :
    whiskerLeft F y ∈ parity (R := R) (F.comp G') (F.comp K') p

theorem whisker_exchange {p q : ZMod 2} {x : F ⟶ H} {y : G' ⟶ K'}
    (hx : x ∈ parity (R := R) F H p) (hy : y ∈ parity (R := R) G' K' q) :
    whiskerRight x G' ≫ whiskerLeft H y = koszulSign p q • (whiskerLeft F y ≫ whiskerRight x K')

theorem IsPiNatural.comp {F G H : C ⥤ D} {hF : PiFunctor R F} {hG : PiFunctor R G}
    {hH : PiFunctor R H} {x : F ⟶ G} {y : G ⟶ H} (hx : IsPiNatural R hF hG x)
    (hy : IsPiNatural R hG hH y) : IsPiNatural R hF hH (x ≫ y)

@[simp] theorem map_map_val (F : C ⥤ D) [F.Additive] [F.Linear R] [IsSuperfunctor R F]
    {X Y : Underlying R C}
    (f : X ⟶ Y) : ((map (R := R) F).map f).1 = F.map f.1

theorem super_interchange_assoc {f g : a ⟶ b} {h i : b ⟶ c} {p q : ZMod 2} {η : f ⟶ g}
    {θ : h ⟶ i} (hη : η ∈ parity (R := R) f g p) (hθ : θ ∈ parity (R := R) h i q) {k : a ⟶ c}
    (ι : g ≫ i ⟶ k) :
    η ▷ h ≫ g ◁ θ ≫ ι = koszulSign p q • (f ◁ θ ≫ η ▷ i ≫ ι)

@[simp] theorem mwhiskerLeft_app (X : DrinfeldCenter R B) {Y Y' : DrinfeldCenter R B}
    (β : Y ⟶ Y') (a : B) :
    (MonoidalCategoryStruct.whiskerLeft X β).app a = β.app a ▷ X.toTwoNatTrans.X a

theorem toHom_whiskerLeft_mem (X : Envelope R C) {Y Y' : Envelope R C} {g : Y ⟶ Y'}
    {r : ZMod 2} (hg : toHom g ∈ parity (R := R) Y.obj Y'.obj r) :
    toHom (X ◁ g) ∈ parity (R := R) (X.obj ⊗ Y.obj) (X.obj ⊗ Y'.obj) r

theorem toHom_whiskerLeft_of_even (X : Envelope R C) {Y Y' : Envelope R C} {g : Y ⟶ Y'}
    (hg : toHom g ∈ parity (R := R) Y.obj Y'.obj 0) (hY : Y.par = Y'.par) :
    toHom (X ◁ g) = X.obj ◁ toHom g

theorem toHom_whiskerLeft_of_mem (X : Envelope R C) {Y Y' : Envelope R C} {g : Y ⟶ Y'}
    {r : ZMod 2} (hg : toHom g ∈ parity (R := R) Y.obj Y'.obj r) :
    toHom (X ◁ g) = sign R (X.par * (r + (Y.par + Y'.par))) • (X.obj ◁ toHom g)

theorem toHom_whiskerRight_mem {X X' : Envelope R C} {f : X ⟶ X'} {r : ZMod 2}
    (hf : toHom f ∈ parity (R := R) X.obj X'.obj r) (Y : Envelope R C) :
    toHom (f ▷ Y) ∈ parity (R := R) (X.obj ⊗ Y.obj) (X'.obj ⊗ Y.obj) r

theorem toHom_whiskerRight_of_even {X X' : Envelope R C} {f : X ⟶ X'}
    (hf : toHom f ∈ parity (R := R) X.obj X'.obj 0) (Y : Envelope R C) :
    toHom (f ▷ Y) = toHom f ▷ Y.obj

theorem toHom_whiskerRight_of_mem {X X' : Envelope R C} {f : X ⟶ X'} {r : ZMod 2}
    (hf : toHom f ∈ parity (R := R) X.obj X'.obj r) (Y : Envelope R C) :
    toHom (f ▷ Y) = sign R (Y.par * r) • (toHom f ▷ Y.obj)

