theorem tensorHom_mem_degree {X X' Y Y' : C} {m n : ℤ} {f : X ⟶ X'} {g : Y ⟶ Y'}
    (hf : f ∈ degree (R := R) X X' m) (hg : g ∈ degree (R := R) Y Y' n) :
